export function sleepMemoryConsolidation(memory) {
  const replayedMemory = memory.filter(item => item.relevanceScore > 0.5);
  replayedMemory.forEach(item => {
    item.strengthenConnections();
  });
  const prunedMemory = memory.filter(item => item.relevanceScore <= 0.5);
  prunedMemory.forEach(item => {
    item.prune();
  });
  return [...replayedMemory, ...prunedMemory];
}